    gameGridResultSkill: 'தேர்ந்தெடுக்கும் கவனம் மற்றும் காட்சி வேறுபாடு',
    gameMarketResultSkill: 'காட்சி நினைவாற்றல் மற்றும் மாற்றம் கண்டறிதல்',
    gameChangedResultSkill: 'காட்சி கவனம் மற்றும் மாற்றம் கண்டறிதல்',
    gameTrailDesc: 'இந்திய பண்பாட்டு அடையாளங்கள், கலை வடிவங்கள் மற்றும் திருவிழாக்களின் ஒரு தொடரைப் பாருங்கள், பின்னர் அதை நினைவிலிருந்து மீண்டும் உருவாக்குங்கள்.',
    gameGridDesc: 'பண்பாட்டுப் பொருட்களின் கட்டத்தை ஆராய்ந்து, நேரம் முடிவதற்குள் அறிவுறுத்தலுக்கு பொருந்தும் பொருட்களை விரைவாகக் கண்டறியுங்கள்.',
    gameMarketDesc: 'பரபரப்பான இந்தியச் சந்தையைப் பாருங்கள், பின்னர் அது மறுசீரமைக்கப்பட்ட பிறகு சரியாக என்ன மாறியது என்பதை நினைவுகூருங்கள்.',
    gameChangedDesc: 'ஒரு பண்பாட்டுக் காட்சியை கவனமாகப் பாருங்கள், பின்னர் மீண்டும் பார்க்கும்போது ஒவ்வொரு மாற்றத்தையும் கண்டறியுங்கள்.',
    gameTrailHow1: 'பண்பாட்டு அட்டைகளின் ஒரு சிறு தொடர் வரிசையாகத் தோன்றுவதைப் பாருங்கள்.',
    gameTrailHow2: 'தொடர் மறைந்தவுடன், அட்டைகளை சரியான வரிசையில் தட்டி மீண்டும் உருவாக்குங்கள்.',
    gameTrailHow3: 'நீங்கள் மேம்படும்போது தொடர்கள் நீளமாகின்றன.',
    gameGridHow1: 'கட்டத்தின் மேலே உள்ள அறிவுறுத்தலைப் படியுங்கள்.',
    gameGridHow2: 'அறிவுறுத்தலுக்கு பொருந்தும் ஒவ்வொரு அட்டையையும் தட்டி, நேரம் முடிவதற்குள் சமர்ப்பிக்கவும்.',
    gameGridHow3: 'நீங்கள் முன்னேறும்போது கட்டம் பெரிதாகி, பொருட்கள் மேலும் ஒத்திருக்கும்.',
    gameMarketHow1: 'சில வினாடிகளுக்கு சந்தையின் ஒவ்வொரு கடையையும் கவனியுங்கள்.',
    gameMarketHow2: 'சந்தை மாறுகிறது — ஒரு பொருள் மறைந்திருக்கலாம், நகர்ந்திருக்கலாம், அல்லது புதிதாகத் தோன்றியிருக்கலாம்.',
    gameMarketHow3: 'காட்டப்பட்ட விருப்பங்களிலிருந்து என்ன மாறியது என்பதற்குப் பதிலளிக்கவும்.',
    gameChangedHow1: 'சில வினாடிகளுக்கு காட்சியை கவனமாகப் பாருங்கள்.',
    gameChangedHow2: 'காட்சி மாறுகிறது — பொருட்கள் நகரலாம், மறையலாம் அல்லது புதிதாகத் தோன்றலாம்.',
    gameChangedHow3: 'முன்பை விட வித்தியாசமாகத் தெரியும் ஒவ்வொரு இடத்திலும் தட்டவும்.',
