    alert1Title: "ಬೆಳಗಿನ ದಿನಚರಿ ಪೂರ್ಣಗೊಂಡಿದೆ",
    alert1Summary: "ಬೆಳಗಿನ ದಿನಚರಿ ಪೂರ್ಣಗೊಂಡಿದೆ — ಉಪಾಹಾರ ಮತ್ತು ಔಷಧಿ ಸಮಯಕ್ಕೆ.",
    alert1Reason: "ಕೇರ್‌ಗಿವರ್ ಪ್ರಿಯಾ ನಿಗದಿತ ಸಮಯದ 15 ನಿಮಿಷಗಳಲ್ಲಿ ಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯನ್ನು ಪರಿಶೀಲಿಸಿದರು.",
    alert2Title: "ಲಾಜಿಕ್ ಆಟದ ವೇಗದಲ್ಲಿ ಸ್ವಲ್ಪ ಬದಲಾವಣೆ",
    alert2Summary: "ಲಾಜಿಕ್ ವಿಂಗಡಣೆ ಆಟದ ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯ 54ಸೆ (ವೈಯಕ್ತಿಕ ಬೇಸ್‌ಲೈನ್: 42ಸೆ).",
    alert2Reason: "ಸಂಜೆಯ ಸಮಯದಲ್ಲಿ ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯದಲ್ಲಿ ತಾತ್ಕಾಲಿಕ 28% ನಿಧಾನಗತಿಯನ್ನು AI ಗುರುತಿಸಿದೆ. ನಿಖರತೆ ಹೆಚ್ಚಾಗಿ (80%) ಇತ್ತು. ಶಿಫಾರಸು ಮಾಡಿದ ತಪಾಸಣೆ: ಬಳಕೆದಾರ ದಣಿದಿಲ್ಲ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.",
