    gameChangedResultSkill: 'ദൃശ്യ ശ്രദ്ധയും മാറ്റം കണ്ടെത്തലും',
    gameTrailDesc: 'ഇന്ത്യൻ സാംസ്കാരിക സ്ഥലങ്ങൾ, കലാരൂപങ്ങൾ, ഉത്സവങ്ങൾ എന്നിവയുടെ ഒരു നിരയെ കാണുക, പിന്നീട് ഓർമ്മയിൽ നിന്ന് അത് പുനർനിർമ്മിക്കുക.',
    gameGridDesc: 'സാംസ്കാരിക വസ്തുക്കളുടെ ഒരു ഗ്രിഡ് സ്കാൻ ചെയ്ത്, സമയം തീരുന്നതിന് മുമ്പ് നിർദ്ദേശവുമായി പൊരുത്തപ്പെടുന്ന വസ്തുക്കൾ വേഗത്തിൽ കണ്ടെത്തുക.',
    gameMarketDesc: 'തിരക്കേറിയ ഒരു ഇന്ത്യൻ ചന്ത കാണുക, പിന്നീട് അത് വീണ്ടും ക്രമീകരിച്ചതിനുശേഷം കൃത്യമായി എന്ത് മാറി എന്ന് ഓർത്തെടുക്കുക.',
    gameChangedDesc: 'ഒരു സാംസ്കാരിക ദൃശ്യം ശ്രദ്ധയോടെ കാണുക, പിന്നീട് വീണ്ടും നോക്കുമ്പോൾ ഓരോ മാറ്റവും കണ്ടെത്തുക.',
    gameTrailHow1: 'സാംസ്കാരിക കാർഡുകളുടെ ഒരു ചെറിയ നിര ക്രമത്തിൽ പ്രത്യക്ഷപ്പെടുന്നത് കാണുക.',
    gameTrailHow2: 'നിര അപ്രത്യക്ഷമായാൽ, കാർഡുകൾ ശരിയായ ക്രമത്തിൽ ടാപ്പ് ചെയ്ത് അത് പുനർനിർമ്മിക്കുക.',
    gameTrailHow3: 'നിങ്ങൾ മെച്ചപ്പെടുന്തോറും നിരകൾ കൂടുതൽ നീളമുള്ളതാകും.',
    gameGridHow1: 'ഗ്രിഡിന് മുകളിലുള്ള നിർദ്ദേശം വായിക്കുക.',
    gameGridHow2: 'നിർദ്ദേശവുമായി പൊരുത്തപ്പെടുന്ന ഓരോ കാർഡും ടാപ്പ് ചെയ്ത്, സമയം തീരുന്നതിന് മുമ്പ് സമർപ്പിക്കുക.',
    gameGridHow3: 'നിങ്ങൾ മുന്നേറുന്തോറും ഗ്രിഡ് വലുതാകുകയും വസ്തുക്കൾ കൂടുതൽ സമാനമാകുകയും ചെയ്യും.',
    gameMarketHow1: 'കുറച്ച് സെക്കൻഡ് ചന്തയിലെ ഓരോ കടയും നിരീക്ഷിക്കുക.',
    gameMarketHow2: 'ചന്ത മാറുന്നു — ഒരു വസ്തു അപ്രത്യക്ഷമാകാം, നീങ്ങാം, അല്ലെങ്കിൽ പുതുതായി പ്രത്യക്ഷപ്പെടാം.',
    gameMarketHow3: 'കാണിച്ച ഓപ്ഷനുകളിൽ നിന്ന് എന്താണ് മാറിയത് എന്ന് ഉത്തരം നൽകുക.',
    gameChangedHow1: 'കുറച്ച് സെക്കൻഡ് ദൃശ്യം ശ്രദ്ധയോടെ കാണുക.',
